import React, { useState } from 'react';
import { useAuth } from '../context/AuthContext';
import { Link, useNavigate } from 'react-router-dom';
import logo from '../../assets/sotacib-logo.jpg';

const DEPARTMENT_OPTIONS = [
  'Finance',
  'Commercial',
  'Ressources Humaines',
  'Systèmes d Information',
  'Investissement',
  'Recouvrement',
  'Fiscal',
  'Direction Générale',
];

const Register = () => {
  const [formData, setFormData] = useState({
    email: '',
    password: '',
    fullName: '',
    department: 'Finance',
  });
  const { register } = useAuth();
  const navigate = useNavigate();

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const success = await register(formData);
    if (success) navigate('/login');
  };

  return (
    <div style={{ position: 'relative', minHeight: '100vh', padding: '24px' }}>
      <div style={{ position: 'absolute', top: '16px', left: '16px' }}>
        <img src={logo} alt="SOTACIB" style={{ width: '140px', height: '140px' }} />
      </div>

      <div className="auth-card max-w-md mx-auto mt-24">
        <h2 className="text-2xl font-bold text-left mb-6">Inscription</h2>
        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label>Nom complet</label>
            <input type="text" name="fullName" value={formData.fullName} onChange={handleChange} required />
          </div>
          <div className="form-group">
            <label>Email</label>
            <input type="email" name="email" value={formData.email} onChange={handleChange} required />
          </div>
          <div className="form-group">
            <label>Mot de passe</label>
            <input type="password" name="password" value={formData.password} onChange={handleChange} required />
          </div>
          <div className="form-group">
            <label>Département</label>
            <select name="department" value={formData.department} onChange={handleChange}>
              {DEPARTMENT_OPTIONS.map((dept) => (
                <option key={dept} value={dept}>{dept}</option>
              ))}
            </select>
          </div>
          <button type="submit" className="btn btn-primary w-full">S'inscrire</button>
        </form>
        <p className="text-center mt-4 text-sm">
          Déjà un compte ? <Link to="/login" className="text-blue-600">Connectez-vous</Link>
        </p>
      </div>
    </div>
  );
};

export default Register;
